  r jsonb; x jsonb; tid bigint; pid bigint; cid bigint; nid smallint; i int;
  getp text := 'select id from people where name_en = $1 and tmdb_id is null';
begin
  for r in select * from jsonb_array_elements(data) loop
    insert into titles (kind, title_th, title_en, release_year, release_month, release_source, series_status, end_year, needs_review)
    values (r->>'k', r->>'th', r->>'en', (r->>'y')::int, (r->>'m')::int, r->>'src', r->>'st', (r->>'end')::int, (r->>'rv')::boolean)
    returning id into tid;
    i := 0;
    for x in select * from jsonb_array_elements(r->'c') loop
      insert into title_countries values (tid, x#>>'{}', i = 0); i := i + 1;
    end loop;
    insert into title_genres select tid, g.id from genres g where g.tmdb_id in (select (v#>>'{}')::int from jsonb_array_elements(r->'g') v);
    i := 0;
    for x in select * from jsonb_array_elements(r->'co') loop
      select id into cid from companies where name = x#>>'{}' and tmdb_id is null;
      if cid is null then insert into companies (name) values (x#>>'{}') returning id into cid; end if;
      insert into title_companies values (tid, cid, i); i := i + 1;
    end loop;
    i := 0;
    for x in select * from jsonb_array_elements(r->'cast') loop
      execute getp into pid using x->>0;
      if pid is null then insert into people (name_en) values (x->>0) returning id into pid; end if;
      insert into title_cast values (tid, pid, nullif(x->>1, ''), i) on conflict do nothing; i := i + 1;
    end loop;
    for x in select * from jsonb_array_elements(r->'d') loop
      execute getp into pid using x#>>'{}';
      if pid is null then insert into people (name_en) values (x#>>'{}') returning id into pid; end if;
      insert into title_creators values (tid, pid, case when r->>'k' = 'series' then 'creator' else 'director' end);
    end loop;
    for x in select * from jsonb_array_elements(r->'net') loop
      select id into nid from networks where name = x->>0;
      if nid is null then insert into networks (name, country) values (x->>0, x->>1) returning id into nid; end if;
      insert into title_networks values (tid, nid);
    end loop;
    i := 1;
    for x in select * from jsonb_array_elements(r->'s') loop
      insert into seasons values (tid, i, null, (x->>0)::int, (x->>1)::int, (x->>2)::int, null); i := i + 1;
    end loop;
  end loop;
end $$;
